```javascript
const axios = require('axios'); // Make sure to install 'axios' package using npm or yarn

async function postMessageToSlackChannel(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.SLACK_BOT_TOKEN}`,
      },
      data: {
        channel,
        text,
      },
    };

    const response = await axios(options);
    console.log(`Message sent to ${channel}: ${response.data.ts}`);
  } catch (error) {
    console.error('Error posting message to Slack:', error.message);
  }
}

// Usage:
postMessageToSlackChannel('Hello, world!', '#general');
```

This function uses the `axios` library for making HTTP requests. The `SLACK_BOT_TOKEN` environment variable should contain your bot token from the Slack App configuration. Make sure to replace `#general` with the actual channel name or ID.

